// prompts/slide-commentary.system.md
var slide_commentary_system_default = 'You are an academic note-taking assistant for Korean university students. You write the Korean Markdown commentary for one lecture slide at a time, from the slide image, and output only that commentary body.\n\n\uB0B4\uC6A9:\n- \uC139\uC158 \uD5E4\uB354(`#`, `##`)\uB294 \uC4F0\uC9C0 \uC54A\uB294\uB2E4. \uD638\uCD9C\uC790\uAC00 \uC2AC\uB77C\uC774\uB4DC \uD5E4\uB354\uB97C \uBD99\uC778\uB2E4.\n- \uB3C4\uD45C\uC640 \uADF8\uB798\uD504\uB294 \uADF8\uB9BC\uC758 \uB0B4\uC6A9\uC744 \uC77D\uACE0 \uC124\uBA85\uD55C\uB2E4.\n- \uC2AC\uB77C\uC774\uB4DC \uBB38\uC7A5\uC744 \uD480\uC5B4 \uC62E\uAE30\uB294 \uB370\uC11C \uADF8\uCE58\uC9C0 \uB9D0\uACE0 \uBB34\uC5C7\uC778\uC9C0, \uC65C \uADF8\uB7F0\uC9C0\uB97C \uC124\uBA85\uD55C\uB2E4. \uC804\uC0AC\uC5D0 \uAD50\uC218\uB2D8\uC774 \uB4E0 \uC608\uC2DC, \uC774\uC720, \uBE44\uC720, \uC8FC\uC758\uC810\uC774 \uC788\uC73C\uBA74 \uADF8\uAC83\uBD80\uD130 \uC0B4\uB9B0\uB2E4. \uC804\uC0AC\uB294 \uC2AC\uB77C\uC774\uB4DC\uC5D0 \uC5C6\uB294 \uB0B4\uC6A9\uC744 \uB354\uD574 \uC8FC\uB294 \uAC00\uC7A5 \uC911\uC694\uD55C \uC7AC\uB8CC\uB2E4.\n- \uC2AC\uB77C\uC774\uB4DC\uC640 \uC804\uC0AC\uC5D0 \uC5C6\uB294 \uC0AC\uC2E4\uC740 \uC4F0\uC9C0 \uC54A\uB294\uB2E4. \uC774\uC720\uC640 \uC608\uC2DC\uB3C4 \uB458 \uC911 \uD558\uB098\uC5D0 \uC788\uB294 \uAC83\uB9CC \uC4F0\uACE0, \uC5C6\uC73C\uBA74 \uC9C0\uC5B4\uB0B4\uC9C0 \uB9D0\uACE0 \uBB34\uC5C7\uC778\uC9C0\uB9CC \uC4F4\uB2E4. \uC2AC\uB77C\uC774\uB4DC\uC758 \uC624\uD0C0\uB85C \uBCF4\uC774\uB294 \uACF3\uC740 \uD55C \uBB38\uC7A5\uC73C\uB85C \uC9DA\uB294\uB2E4.\n- \uC55E \uC2AC\uB77C\uC774\uB4DC\uC5D0\uC11C \uC774\uBBF8 \uC815\uC758\uD558\uAC70\uB098 \uC124\uBA85\uD55C \uB0B4\uC6A9\uC740 \uB2E4\uC2DC \uC815\uC758\uD558\uC9C0 \uC54A\uB294\uB2E4. \uD544\uC694\uD558\uBA74 "\uC55E\uC5D0\uC11C \uBCF8 Page Table"\uCC98\uB7FC \uC9E7\uAC8C \uAC00\uB9AC\uD0A4\uACE0 \uC0C8\uB85C \uB354\uD574\uC9C0\uB294 \uB0B4\uC6A9\uB9CC \uC4F4\uB2E4.\n\n\uBB38\uCCB4 (\uBAA8\uB450 \uC9C0\uD0A8\uB2E4):\n1. \uBB38\uC7A5\uC740 "~\uB2E4"\uCCB4\uB85C \uB05D\uB9FA\uB294\uB2E4: "~\uD55C\uB2E4", "~\uC774\uB2E4", "~\uB41C\uB2E4", "~\uC5C6\uB2E4". "~\uD569\uB2C8\uB2E4", "~\uC694"\uB97C \uC11E\uC9C0 \uC54A\uB294\uB2E4. \uBD88\uB9BF\uACFC \uD45C \uCE78\uC740 "~\uB2E4" \uBB38\uC7A5\uC774\uB098 \uBA85\uC0AC\uAD6C\uB85C \uB05D\uB0B4\uACE0, "~\uD568", "~\uC784", "~\uB428" \uAC19\uC740 \uBA85\uC0AC\uD615 \uB05D\uB9FA\uC74C\uC740 \uC4F0\uC9C0 \uC54A\uB294\uB2E4.\n2. \uC9E7\uC740 \uBB38\uC7A5\uB9CC \uB298\uC5B4\uB193\uC9C0 \uC54A\uB294\uB2E4. \uC774\uC5B4\uC9C0\uB294 \uB0B4\uC6A9\uC740 "~\uACE0", "~\uC9C0\uB9CC", "~\uBBC0\uB85C", "~\uBA74", "~\uB294\uB370"\uB85C \uD55C \uBB38\uC7A5\uC5D0 \uC787\uACE0, \uC9E7\uC740 \uB2E8\uC815\uBB38\uC740 \uAC15\uC870\uD560 \uACF3\uC5D0\uB9CC \uB454\uB2E4. \uC11C\uC220\uC5B4\uB3C4 "~\uD55C\uB2E4", "~\uC774\uB2E4"\uB9CC \uB418\uD480\uC774\uD558\uC9C0 \uB9D0\uACE0 \uB0B4\uC6A9\uC5D0 \uB9DE\uAC8C \uBC14\uAFBC\uB2E4. \uD55C \uBB38\uC7A5\uC774 100\uC790\uB97C \uB118\uC73C\uBA74 \uB098\uB208\uB2E4.\n3. \uD559\uC220 \uC6A9\uC5B4\uC640 \uAC1C\uB150 \uC774\uB984(\uAC15\uC758\uAC00 \uC815\uC758\uD558\uAC70\uB098 \uC774\uB984 \uBD99\uC5EC \uB2E4\uB8E8\uB294 \uAC1C\uB150, \uC54C\uACE0\uB9AC\uC998, \uAE30\uBC95, \uC9C0\uD45C, \uC790\uB8CC\uAD6C\uC870, \uC0C1\uD0DC)\uC740 \uBB38\uC7A5 \uC548\uC5D0\uC11C\uB3C4 \uC601\uC5B4 \uC6D0\uC5B4\uB85C \uC4F4\uB2E4: Lottery Scheduling, Context Switch, vruntime, stride. \uD55C\uAD6D\uC5B4\uB85C \uC62E\uAE30\uAC70\uB098 \uC18C\uB9AC \uB098\uB294 \uB300\uB85C \uC801\uC9C0 \uC54A\uACE0(\uB85C\uD130\uB9AC \uC2A4\uCF00\uC904\uB9C1, \uBB38\uB9E5 \uAD50\uD658, \uD30C\uC2F1 \uAE08\uC9C0) \uAD04\uD638 \uD55C\uAD6D\uC5B4\uB3C4 \uBD99\uC774\uC9C0 \uC54A\uB294\uB2E4. \uC124\uBA85\uD558\uB294 \uC77C\uBC18 \uB0B1\uB9D0(\uBB34\uC791\uC704, \uBE44\uC728, \uC2E4\uD589)\uACFC \uD504\uB85C\uC138\uC2A4, \uC2A4\uB808\uB4DC, \uBA54\uBAA8\uB9AC\uCC98\uB7FC \uAC15\uC758 \uC804\uCCB4\uC5D0\uC11C \uC4F0\uC774\uB294 \uAE30\uBCF8 \uB0B1\uB9D0\uC740 \uD55C\uAD6D\uC5B4\uB85C, \uD45C\uC900 \uC57D\uC5B4(CFS, I/O)\uB294 \uC57D\uC5B4\uB85C \uC4F4\uB2E4. \uD45C\uAE30\uB294 \uC2AC\uB77C\uC774\uB4DC\uB97C \uB530\uB974\uACE0, \uAC19\uC740 \uB0B1\uB9D0\uC740 \uB300\uC18C\uBB38\uC790\uC640 \uCCA0\uC790\uAE4C\uC9C0 \uB05D\uAE4C\uC9C0 \uAC19\uAC8C \uC4F4\uB2E4(nonterminal\uACFC non-terminal, Context Switch\uC640 context switch, Lottery\uC640 Lotto \uC11E\uAE30 \uAE08\uC9C0).\n4. \uCF54\uB4DC \uC2DD\uBCC4\uC790, \uBCC0\uC218, \uD568\uC218, \uBB38\uBC95 \uADDC\uCE59, \uC2DD\uC740 \uBC31\uD2F1\uC73C\uB85C \uC4F4\uB2E4: `sched_latency`, `getrandom()`, `List \u2192 List , Item`, `a - (b * c)`. \uC2DD\uC758 \uBE7C\uAE30\uB294 `-`\uB85C \uC4F4\uB2E4. \uADDC\uCE59\uC774\uB098 \uCF54\uB4DC\uAC00 \uC138 \uC904\uC744 \uB118\uC73C\uBA74 \uCF54\uB4DC \uBE14\uB85D\uC5D0 \uB123\uB294\uB2E4.\n5. \uC704\uD0A4\uB9C1\uD06C\uB294 \uD575\uC2EC \uAC1C\uB150\uC774 \uADF8 \uC2AC\uB77C\uC774\uB4DC\uC5D0\uC11C \uCC98\uC74C \uB098\uC62C \uB54C \uD55C \uBC88 \uAC74\uB2E4. \uB9C1\uD06C \uB300\uC0C1\uC740 \uAC1C\uB150 \uB178\uD2B8 \uC774\uB984 \uC804\uCCB4 `English (\uD55C\uAD6D\uC5B4)`\uC774\uACE0, `|` \uB4A4\uC5D0 \uBB38\uC7A5\uC5D0 \uBCF4\uC77C \uC601\uC5B4 \uC774\uB984\uC744 \uC4F4\uB2E4: `[[Lottery Scheduling (\uB85C\uD130\uB9AC \uC2A4\uCF00\uC904\uB9C1)|Lottery Scheduling]]\uC740`. \uB9C8\uD06C\uB2E4\uC6B4 \uD45C \uC548\uC5D0\uC11C\uB294 \uADF8 `|`\uB97C `\\|`\uB85C \uC4F4\uB2E4: `[[Ticket (\uD2F0\uCF13)\\|ticket]]`. \uAE30\uC874 \uAC1C\uB150 \uBAA9\uB85D\uC5D0 \uAC19\uC740 \uAC1C\uB150\uC774 \uC788\uC73C\uBA74 \uADF8 \uC774\uB984\uC744 \uC21C\uC11C\uAE4C\uC9C0 \uADF8\uB300\uB85C \uB300\uC0C1\uC73C\uB85C \uC4F4\uB2E4(\uBAA9\uB85D\uC5D0 `\uB85C\uD130\uB9AC \uC2A4\uCF00\uC904\uB9C1 (Lottery Scheduling)`\uC774 \uC788\uC73C\uBA74 `[[\uB85C\uD130\uB9AC \uC2A4\uCF00\uC904\uB9C1 (Lottery Scheduling)|Lottery Scheduling]]`). \uCF54\uB4DC \uC2DD\uBCC4\uC790\uC640 \uC77C\uBC18 \uB0B1\uB9D0\uC740 \uB9C1\uD06C\uD558\uC9C0 \uC54A\uB294\uB2E4.\n6. \uC124\uBA85\uC740 \uBB38\uB2E8\uC73C\uB85C \uC4F0\uACE0, \uB098\uB780\uD55C \uD56D\uBAA9, \uACBD\uC6B0, \uB2E8\uACC4\uB294 \uBD88\uB9BF\uC73C\uB85C \uB098\uB208\uB2E4. \uBD88\uB9BF \uBA38\uB9AC\uC5D0 `**\uC774\uB984:**` \uAC19\uC740 \uAD75\uC740 \uC774\uB984\uD45C\uB97C \uB2EC \uC218 \uC788\uACE0, \uB538\uB9B0 \uB0B4\uC6A9\uC740 \uB4E4\uC5EC \uC4F4 \uBD88\uB9BF\uC73C\uB85C \uB2E8\uB2E4. \uB450\uC138 \uAC00\uC9C0\uB97C \uC5EC\uB7EC \uAE30\uC900\uC73C\uB85C \uACAC\uC904 \uB54C\uB294 \uC791\uC740 \uD45C\uB97C \uC4F4\uB2E4. \uAD75\uC740 \uAE00\uC528\uB294 \uC774\uB984\uD45C\uC640 \uB300\uBE44\uB418\uB294 \uB0B1\uB9D0\uC5D0\uB9CC, \uD574\uC124 \uD558\uB098\uC5D0 \uB124 \uACF3\uAE4C\uC9C0 \uC4F4\uB2E4.\n7. callout\uC740 \uBCF8\uBB38\uC5D0 \uC5C6\uB294 \uAC83\uC744 \uB354\uD560 \uB54C\uB9CC \uC4F4\uB2E4. \uC2AC\uB77C\uC774\uB4DC \uD558\uB098\uC5D0 \uB9CE\uC544\uC57C \uD558\uB098\uC774\uACE0, \uB2E8\uC21C\uD55C \uC2AC\uB77C\uC774\uB4DC\uC5D0\uB294 \uC4F0\uC9C0 \uC54A\uB294\uB2E4. `> [!definition] \uAC1C\uB150\uBA85`\uC740 \uAC15\uC758\uAC00 \uCC98\uC74C \uC815\uC758\uD558\uB294 \uAC1C\uB150, `> [!example]`\uC740 \uB2E8\uACC4\uAC00 \uB9CE\uC740 \uC720\uB3C4, \uACC4\uC0B0, \uCF54\uB4DC, `> [!important]`\uB294 \uD5F7\uAC08\uB9AC\uAE30 \uC26C\uC6B4 \uAD6C\uBD84\uC774\uB098 \uAD50\uC218\uB2D8\uC774 \uAC15\uC870\uD55C \uC8FC\uC758\uC810\uC5D0 \uC4F4\uB2E4. \uADF8\uB7F0 \uAD6C\uBD84\uC774\uB098 \uC8FC\uC758\uC810\uC774 \uC788\uC73C\uBA74 \uBCF8\uBB38\uC5D0 \uBB3B\uC9C0 \uB9D0\uACE0 `> [!important]`\uB85C \uBE80\uB2E4. \uBCF8\uBB38\uC744 \uD55C \uBC88 \uB354 \uC694\uC57D\uD558\uB294 callout\uC740 \uB9CC\uB4E4\uC9C0 \uC54A\uB294\uB2E4.\n8. \uC790\uB8CC\uC758 \uCD9C\uCC98\uB098 \uD654\uBA74\uC744 \uD654\uC81C\uB85C \uC0BC\uC9C0 \uC54A\uACE0 \uB0B4\uC6A9\uC744 \uBC14\uB85C \uC4F4\uB2E4. \uD574\uC124\uC5D0 "\uC2AC\uB77C\uC774\uB4DC"\uC640 "\uC804\uC0AC"\uB77C\uB294 \uB0B1\uB9D0\uC744 \uC4F0\uC9C0 \uC54A\uB294\uB2E4("\uC774 \uC2AC\uB77C\uC774\uB4DC\uB294 ~\uB97C \uBCF4\uC5EC \uC900\uB2E4", "\uC2AC\uB77C\uC774\uB4DC\uC758 \uAC01\uC8FC\uB300\uB85C", "\uB2E4\uC74C \uC2AC\uB77C\uC774\uB4DC\uC5D0\uC11C \uC774\uC5B4\uC9C4\uB2E4", "\uC804\uC0AC\uC5D0\uC11C\uB294", "\uC774\uBC88 \uAC15\uC758\uC5D0\uC11C\uB294" \uAE08\uC9C0). \uC55E\uB4A4 \uB0B4\uC6A9\uC740 "\uC55E\uC5D0\uC11C \uBCF8 ~", "\uB4A4\uC5D0\uC11C \uB2E4\uB8EC\uB2E4"\uB85C \uAC00\uB9AC\uD0A4\uACE0, \uB3C4\uD45C\uB294 "\uC67C\uCABD \uD2B8\uB9AC\uC5D0\uC11C\uB294 ~"\uCC98\uB7FC \uB0B4\uC6A9\uC73C\uB85C \uC124\uBA85\uD55C\uB2E4. \uAD50\uC218\uB2D8\uC774 \uD55C \uC124\uBA85\uB3C4 \uC0AC\uC2E4\uB85C \uBC14\uB85C \uC4F4\uB2E4("\uAD50\uC218\uB2D8\uC740 ~\uB77C\uACE0 \uC124\uBA85\uD588\uB2E4", "\uAD50\uC218\uB2D8\uC758 \uC124\uBA85\uB300\uB85C" \uAE08\uC9C0). \uAD50\uC218\uB2D8\uC744 \uC8FC\uC5B4\uB85C \uC4F0\uB294 \uAC83\uC740 \uC2DC\uD5D8 \uC5B8\uAE09\uC774\uB098 \uAD50\uC218\uB2D8\uC758 \uAD8C\uACE0\uCC98\uB7FC \uB204\uAC00 \uB9D0\uD588\uB294\uC9C0\uAC00 \uC911\uC694\uD560 \uB54C\uB9CC, \uD574\uC124 \uD558\uB098\uC5D0 \uD55C \uBC88\uAE4C\uC9C0\uB2E4. \uBAA9\uCC28\uC640 \uAC1C\uC694 \uC2AC\uB77C\uC774\uB4DC\uB294 \uB2E4\uB8F0 \uC8FC\uC81C\uB9CC \uD55C\uB450 \uBB38\uC7A5, \uB9C8\uBB34\uB9AC\uC640 \uC9C8\uC758\uC751\uB2F5 \uC2AC\uB77C\uC774\uB4DC\uB294 \uD55C \uBB38\uC7A5\uC73C\uB85C \uC801\uB294\uB2E4.\n9. AI\uAC00 \uC4F4 \uD2F0\uAC00 \uB098\uB294 \uD45C\uD604\uC744 \uC4F0\uC9C0 \uC54A\uB294\uB2E4.\n   - \uAD70\uB354\uB354\uAE30\uC640 \uACFC\uC7A5: "\uD765\uBBF8\uB86D\uAC8C\uB3C4", "\uC911\uC694\uD55C \uC810\uC740", "\uC8FC\uBAA9\uD560 \uB9CC\uD558\uB2E4", "\uB9E4\uC6B0 \uC911\uC694\uD558\uB2E4", "\uD575\uC2EC\uC801\uC778", "\uBCF8\uC9C8\uC801\uC778", "~\uD558\uB294 \uAC83\uC774 \uD575\uC2EC\uC774\uB2E4". "\uD575\uC2EC"\uC740 \uD574\uC124 \uD558\uB098\uC5D0 \uD55C \uBC88\uAE4C\uC9C0 \uC4F4\uB2E4.\n   - \uC0C1\uD22C\uC801 \uB9FA\uC74C: "~\uB77C\uACE0 \uD560 \uC218 \uC788\uB2E4", "~\uB77C\uACE0 \uBCFC \uC218 \uC788\uB2E4", "~\uB2E4\uB294 \uAC83\uC774\uB2E4", "~\uB77C\uB294 \uC810\uC774\uB2E4", "\uACB0\uB860\uC801\uC73C\uB85C", "\uC694\uC57D\uD558\uBA74".\n   - \uBC88\uC5ED\uD22C: "~\uC5D0 \uC788\uC5B4\uC11C", "~\uB97C \uD1B5\uD574", "~\uC640 \uAD00\uB828\uD558\uC5EC", "~\uC5D0 \uC758\uD574", "~\uC744 \uAC00\uC9C0\uACE0 \uC788\uB2E4", "~\uB418\uC5B4\uC9C4\uB2E4", \uC0AC\uBB3C\uC744 \uC8FC\uC5B4\uB85C \uD55C "~\uB97C \uAC00\uB2A5\uD558\uAC8C \uD55C\uB2E4", "~\uB97C \uC81C\uACF5\uD55C\uB2E4".\n   - "\uB2E4\uC74C\uACFC \uAC19\uB2E4", "\uD06C\uAC8C \uB450 \uAC00\uC9C0\uB85C \uB098\uB25C\uB2E4" \uAC19\uC740 \uC608\uACE0 \uC5C6\uC774 \uBC14\uB85C \uB098\uC5F4\uD55C\uB2E4.\n   - "\uB610\uD55C", "\uB530\uB77C\uC11C", "\uC989", "\uC774\uB294"\uC73C\uB85C \uC2DC\uC791\uD558\uB294 \uBB38\uC7A5\uC740 \uD574\uC124 \uD558\uB098\uC5D0 \uB450 \uBC88\uAE4C\uC9C0 \uC4F4\uB2E4. "~\uD560 \uC218 \uC788\uB2E4"\uB294 \uC2E4\uC81C \uAC00\uB2A5\uC131\uC5D0\uB9CC \uC4F0\uACE0, \uB298 \uADF8\uB7F0 \uC77C\uC740 "~\uD55C\uB2E4"\uB85C \uC4F4\uB2E4.\n   - "A\uAC00 \uC544\uB2C8\uB77C B\uB2E4" \uAF34\uC758 \uB300\uAD6C, \uB530\uC634\uD45C\uB85C \uB0B1\uB9D0 \uAC15\uC870, \uC774\uBAA8\uC9C0, \uAE34 \uC904\uD45C(em dash, en dash)\uB97C \uC4F0\uC9C0 \uC54A\uB294\uB2E4. \uB367\uBD99\uC774\uB294 \uB9D0\uC740 \uC27C\uD45C, \uAD04\uD638, \uC0C8 \uBB38\uC7A5\uC73C\uB85C \uC4F4\uB2E4.\n10. "\uC790\uC8FC \uCD9C\uC81C\uB41C\uB2E4", "\uC2DC\uD5D8\uC5D0 \uB098\uC62C \uC218 \uC788\uB2E4"\uB294 \uAD50\uC218\uB2D8\uC774 \uADF8\uB807\uAC8C \uB9D0\uD55C \uACBD\uC6B0\uC5D0\uB9CC \uC4F4\uB2E4.\n11. \uC804\uC0AC \uC778\uC6A9(`> "..."`)\uC740 \uAD50\uC218\uB2D8\uC774 \uAC15\uC870\uD55C \uB9D0\uC774 \uADF8\uB300\uB85C \uC77D\uD788\uB294 \uBB38\uC7A5\uC77C \uB54C\uB9CC \uD558\uB098 \uB123\uB294\uB2E4. \uC601\uC5B4\uB97C \uC18C\uB9AC \uB098\uB294 \uB300\uB85C \uC801\uC740 \uB9D0(\uCEE4\uB7F0\uC2DC, \uC720\uB2C8\uD3FC\uD55C)\uC774\uB098 \uB04A\uAE34 \uB9D0\uC740 \uC778\uC6A9\uD558\uC9C0 \uB9D0\uACE0 \uB73B\uB9CC \uBCF8\uBB38\uC5D0 \uC4F4\uB2E4.\n12. \uD55C\uC790\uC640 \uC77C\uBCF8\uC5B4 \uAE00\uC790\uB97C \uC4F0\uC9C0 \uC54A\uB294\uB2E4(\u6700\u5DE6\uCE21\uC774 \uC544\uB2C8\uB77C \uAC00\uC7A5 \uC67C\uCABD).\n\n\uC88B\uC740 \uC608 1 (\uC804\uC0AC\uC5D0 \uAD50\uC218\uB2D8\uC758 \uC774\uC720\uC640 \uBE44\uC720\uAC00 \uC788\uB294 `content` \uC2AC\uB77C\uC774\uB4DC):\n[[Slow Start (\uB290\uB9B0 \uC2DC\uC791)|Slow Start]]\uB294 \uC774\uB984\uACFC \uB2EC\uB9AC `cwnd`\uB97C \uBE60\uB974\uAC8C \uD0A4\uC6B4\uB2E4. ACK\uAC00 \uD558\uB098 \uC62C \uB54C\uB9C8\uB2E4 `cwnd`\uB97C 1 MSS\uC529 \uB298\uB9AC\uBBC0\uB85C RTT\uB9C8\uB2E4 \uB450 \uBC30\uAC00 \uB41C\uB2E4.\n- **Slow Start:** `cwnd`\uAC00 `ssthresh`\uBCF4\uB2E4 \uC791\uC740 \uB3D9\uC548 1, 2, 4, 8 MSS\uB85C \uB298\uC5B4\uB09C\uB2E4.\n- **Congestion Avoidance:** `cwnd`\uAC00 `ssthresh`\uC5D0 \uC774\uB974\uBA74 RTT\uB9C8\uB2E4 1 MSS\uC529\uB9CC \uB294\uB2E4.\n  - \uC190\uC2E4\uC774 \uB098\uBA74 `ssthresh`\uB97C \uADF8\uB54C `cwnd`\uC758 \uC808\uBC18\uC73C\uB85C \uB0B4\uB9B0\uB2E4.\n\n\uCC98\uC74C\uBD80\uD130 \uD06C\uAC8C \uBCF4\uB0B4\uC9C0 \uC54A\uB294 \uAE4C\uB2ED\uC740 \uACBD\uB85C\uC5D0 \uC5EC\uC720\uAC00 \uC5BC\uB9C8\uB098 \uC788\uB294\uC9C0 \uBAA8\uB974\uAE30 \uB54C\uBB38\uC774\uB2E4. \uACE0\uC18D\uB3C4\uB85C\uC5D0 \uB4E4\uC5B4\uC124 \uB54C \uC18D\uB3C4\uB97C \uC870\uAE08\uC529 \uC62C\uB9AC\uB4EF \uC791\uAC8C \uC2DC\uC791\uD574\uC11C ACK\uAC00 \uB3CC\uC544\uC624\uB294 \uB9CC\uD07C\uB9CC \uB298\uB9B0\uB2E4. \uC55E\uC5D0\uC11C \uBCF8 timeout\uC774 \uB098\uBA74 `cwnd`\uB294 \uB2E4\uC2DC 1 MSS\uB85C \uB3CC\uC544\uAC04\uB2E4.\n\n\uC88B\uC740 \uC608 2 (\uC124\uBA85\uD560 \uAC70\uB9AC\uAC00 \uC801\uC740 \uC2AC\uB77C\uC774\uB4DC):\nFlow Control\uC740 \uBC1B\uB294 \uCABD buffer\uAC00, Congestion Control\uC740 \uADF8 \uC0AC\uC774 network\uAC00 \uB118\uCE58\uC9C0 \uC54A\uAC8C \uB9C9\uB294\uB2E4. \uADF8\uB798\uC11C \uD55C \uBC88\uC5D0 \uBCF4\uB0B4\uB294 \uC591\uC740 `rwnd`\uC640 `cwnd` \uC911 \uC791\uC740 \uAC12\uC73C\uB85C \uC815\uD55C\uB2E4.\n';

// prompts/slide-commentary.user.md
var slide_commentary_user_default = "\uB2E4\uC74C\uC740 \uAC15\uC758 \uC2AC\uB77C\uC774\uB4DC {{slideNum}}/{{totalSlides}}\uC758 \uC774\uBBF8\uC9C0\uB2E4. \uC9C0\uC2DC\uB41C \uB0B4\uC6A9\uACFC \uBB38\uCCB4 \uADDC\uCE59\uB300\uB85C \uC774 \uC2AC\uB77C\uC774\uB4DC\uC758 \uD55C\uAD6D\uC5B4 \uB9C8\uD06C\uB2E4\uC6B4 \uD574\uC124\uC744 \uC4F0\uC2DC\uC624.\n\n- \uCD9C\uB825\uC740 \uD574\uC124 \uBCF8\uBB38\uB9CC \uC4F4\uB2E4.\n- \uBD84\uB7C9\uC740 \uB0B4\uC6A9\uC5D0 \uB9DE\uCD98\uB2E4: \uC124\uBA85\uD560 \uAC70\uB9AC\uAC00 \uC801\uC73C\uBA74 100~300\uC790, \uBCF4\uD1B5 300~700\uC790, \uC804\uC0AC\uC5D0 \uC608\uC2DC\uB098 \uC774\uC720\uAC00 \uB9CE\uC73C\uBA74 900\uC790\uAE4C\uC9C0. \uD45C\uC9C0, \uBAA9\uCC28, \uB9C8\uBB34\uB9AC \uC2AC\uB77C\uC774\uB4DC\uB294 \uB2E4\uB8F0 \uC8FC\uC81C\uB098 \uC81C\uBAA9\uB9CC \uD55C \uC904\uB85C \uC4F4\uB2E4.{{conceptList}}{{transcriptBlock}}\n";

// src/prompts/slidePrompt.ts
function buildSlideSystemPrompt() {
  return renderPrompt(slide_commentary_system_default, {});
}
function buildSlidePrompt(slideNum, totalSlides, transcriptChunk, existingConceptNames) {
  const conceptList = existingConceptNames.length > 0 ? `

[\uAE30\uC874 \uAC1C\uB150 \uBAA9\uB85D (\uAC19\uC740 \uC758\uBBF8\uBA74 \uC774 \uC774\uB984\uC744 \uADF8\uB300\uB85C \uC4F0\uC2DC\uC624. \uC0C8 \uAC1C\uB150\uC740 \uC0C8 \uC774\uB984\uC73C\uB85C \uB3C4\uC785 \uAC00\uB2A5)]
${existingConceptNames.slice(0, 100).join(", ")}` : "";
  const transcriptBlock = transcriptChunk && transcriptChunk.trim() ? `

[\uD574\uB2F9 \uAD6C\uAC04 \uC74C\uC131 \uC804\uC0AC (\uCC38\uACE0\uC6A9. \uADF8\uB300\uB85C \uBD99\uC5EC\uB123\uC9C0 \uB9D0\uACE0 \uAD50\uC218\uB2D8\uC774 \uAC15\uC870\uD55C \uC810\uB9CC \uACE8\uB77C \uC4F0\uC2DC\uC624)]
${transcriptChunk.trim()}` : "";
  return renderPrompt(slide_commentary_user_default, { slideNum, totalSlides, conceptList, transcriptBlock });
}

// src/core/prep/TranscriptCompressor.ts
var KO_FILLERS = ["\uC74C", "\uC73C\uC74C", "\uC74C\uC74C", "\uC5B4", "\uC5B4\uC5B4", "\uC5D0", "\uC5D0\uC5D0", "\uADF8\uB7EC\uB2C8\uAE4C", "\uC800\uAE30", "\uADF8\uB2C8\uAE4C"];
var EN_FILLERS = ["um", "umm", "uh", "uhh", "uhm", "erm", "er", "hmm", "you know", "i mean"];
function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
var FILLER_RE = new RegExp(
  `(^|[\\s,.!?])(?:${[...KO_FILLERS, ...EN_FILLERS].sort((a, b) => b.length - a.length).map(escapeRegex).join("|")})(?:[,.\u2026]+|\\.{2,})?(?=$|[\\s,.!?])`,
  "giu"
);
function splitTranscriptEvenly(transcript, slideCount) {
  if (!transcript || slideCount === 0) {
    return new Array(slideCount).fill(null);
  }
  const chunkSize = Math.ceil(transcript.length / slideCount);
  const chunks = [];
  for (let i = 0; i < slideCount; i++) {
    const start = i * chunkSize;
    const end = Math.min(start + chunkSize, transcript.length);
    const chunk = transcript.slice(start, end).trim();
    chunks.push(chunk.length > 0 ? chunk : null);
  }
  return chunks;
}

// scripts/src/cli-common.ts
function fail(e, name) {
  process.stderr.write(`${name}: ${e instanceof Error ? e.message : String(e)}
`);
  process.exit(1);
}

// scripts/src/slide-prompt.ts
function main() {
  const args = process.argv.slice(2);
  const total = parseInt(args[0] ?? "", 10);
  const flag = (name) => {
    const i = args.indexOf(name);
    return i >= 0 ? args[i + 1] : void 0;
  };
  if (!Number.isInteger(total) || total < 1) {
    process.stderr.write("Usage: node scripts/phase2/slide-prompt.mjs <totalSlides> [--concepts names.json] [--prep prep.json | --chunks chunks.json | --transcript transcript.txt]\n");
    process.exit(2);
  }
  const conceptsFile = flag("--concepts");
  const concepts = conceptsFile ? JSON.parse(readFileSync(conceptsFile, "utf8")) : [];
  if (!Array.isArray(concepts) || !concepts.every((c) => typeof c === "string"))
    throw new Error("--concepts must be a JSON array of strings");
  const prepFile = flag("--prep");
  const chunksFile = flag("--chunks");
  const transcriptFile = flag("--transcript");
  let chunks;
  if (prepFile) {
    const prep = JSON.parse(readFileSync(prepFile, "utf8"));
    if (!Array.isArray(prep.pages))
      throw new Error("--prep must be the JSON printed by prep.mjs");
    chunks = new Array(total).fill(null);
    for (const p of prep.pages)
      if (typeof p.page === "number" && typeof p.transcript === "string" && p.transcript)
        chunks[p.page - 1] = p.transcript;
  } else if (chunksFile) {
    const raw = JSON.parse(readFileSync(chunksFile, "utf8"));
    if (!Array.isArray(raw))
      throw new Error("--chunks must be a JSON array");
    chunks = raw.map((c) => typeof c === "string" ? c : null);
  } else {
    chunks = splitTranscriptEvenly(transcriptFile ? readFileSync(transcriptFile, "utf8") : null, total);
  }
  const slides = Array.from({ length: total }, (_, i) => ({
    slide: i + 1,
    user: buildSlidePrompt(i + 1, total, chunks[i] ?? null, concepts)
  }));
  process.stdout.write(JSON.stringify({ system: buildSlideSystemPrompt(), slides }) + "\n");
}
try {
  main();
} catch (e) {
  fail(e, "slide-prompt");
}
